-- 국내 제조사 가격·연비 조인 결과 확인일: 2026-10-14.
-- 기준 파일: domestic-vehicle-details.csv. 가격·연비 원본 CSV는 조인 검증용이다.
-- 판매가격과 연료 코드가 있는 트림만 넣는다. 판매가 미확인, 연료 공란은 제외한다.
-- 같은 제조사·모델·트림·연식·연료·파워트레인의 가격만 다른 행은 연비가 연결된 행을 우선하고, 같으면 더 낮은 기본가를 남긴다.
-- 모닝은 기존 공식 시드와 가격이 달라 제외한다. 레이는 기존과 같은 가격 4트림을 제외한다.
-- K5 프레스티지 1.6 터보 29,730,000원은 기존 시드와 같으므로 제외한다.
-- price는 표시 판매가이며, 가격 기준이 세제혜택 후인 행은 혜택 후 금액이다.
-- price_before_incentive는 세제혜택 전 가격이 판매가와 다를 때만 저장한다.
-- 차급은 모델 기준 시드 규약이며 DB CHECK로 강제하지 않는다.
-- 실매물이 아니므로 is_example = TRUE. 이미지 주소는 만들지 않는다.
-- 동일 제조사·차명·트림·파워트레인·연식·신차·연료가 있으면 건너뛴다.

ALTER TABLE vehicles
 ADD COLUMN powertrain VARCHAR(40) NULL AFTER trim_name,
 ADD COLUMN displacement_cc INT NULL AFTER seating_capacity,
 ADD COLUMN price_before_incentive DECIMAL(15,2) NULL AFTER price,
 ADD COLUMN city_efficiency DECIMAL(10,3) NULL AFTER efficiency_value,
 ADD COLUMN highway_efficiency DECIMAL(10,3) NULL AFTER city_efficiency,
 ADD COLUMN wheel_size_inch INT NULL AFTER efficiency_unit;

INSERT INTO brands (name)
SELECT seed.name
FROM (
 SELECT '제네시스' AS name
 UNION ALL SELECT '르노코리아'
 UNION ALL SELECT 'KG모빌리티'
 UNION ALL SELECT '쉐보레'
) AS seed
WHERE NOT EXISTS (SELECT 1 FROM brands existing WHERE existing.name = seed.name);

INSERT INTO vehicles (
 brand_id, name, trim_name, powertrain, model_year, condition_code, class_code, fuel_code,
 seating_capacity, displacement_cc, price, price_before_incentive, efficiency_value,
 city_efficiency, highway_efficiency, efficiency_unit, wheel_size_inch, image_url,
 source_name, source_url, is_example
)
SELECT brand.id, seed.name, seed.trim_name, seed.powertrain, seed.model_year, 'NEW', seed.class_code,
 seed.fuel_code, NULL, seed.displacement_cc, seed.price, seed.price_before_incentive, seed.efficiency_value,
 seed.city_efficiency, seed.highway_efficiency, seed.efficiency_unit, seed.wheel_size_inch, NULL,
